  const bufA = crypto.createHash('sha256').update(String(a === undefined || a === null ? '' : a)).digest();
  const bufB = crypto.createHash('sha256').update(String(b === undefined || b === null ? '' : b)).digest();
  return crypto.timingSafeEqual(bufA, bufB);
