  if (token === null || token === undefined || String(token) === '') return '[empty]';
  const s = String(token);
  if (s.length <= 8) return '[REDACTED:' + s.length + 'chars]';
  return s.slice(0, 4) + '…' + s.slice(-2) + ' (' + s.length + ' chars)';
